            print(f'{proj}: {pkg} {bv} -> {av}')
if not changes:
    print('No changes (besides CPM centralization)')

print()
print('=== Unchanged ===')
for proj in sorted(bp.keys()):
    for pkg in sorted(bp.get(proj,{}).keys()):
        bv = bp[proj][pkg]
        av = ap.get(proj,{}).get(pkg)
        if bv == av:
            print(f'{proj}: {pkg} = {bv}')
